        testes.add(DynamicTest.dynamicTest("interesses/nome: obrigatório", () -> assertThrows(ErroDominio.class, () -> new ManifestacaoInteresse(Controle.novo(Estado.ATIVO), null, "ana.lima@example.com", "(81) 98888-0002", "Estudante de Sistemas", "oficinas-0", "Pendente"))));
