        testes.add(DynamicTest.dynamicTest("interesses/nome: texto curto", () -> assertThrows(ErroDominio.class, () -> new ManifestacaoInteresse(Controle.novo(Estado.ATIVO), "x", "ana.lima@example.com", "(81) 98888-0002", "Estudante de Sistemas", "oficinas-0", "Pendente"))));
