        testes.add(DynamicTest.dynamicTest("interesses/telefone: poucos dígitos", () -> assertThrows(ErroDominio.class, () -> new ManifestacaoInteresse(Controle.novo(Estado.ATIVO), "Ana Lima", "ana.lima@example.com", "1234-567", "Estudante de Sistemas", "oficinas-0", "Pendente"))));
