        testes.add(DynamicTest.dynamicTest("interesses/situacao: começa pendente", () -> assertTrue(new ManifestacaoInteresse(Controle.novo(Estado.ATIVO), "Ana Lima", "ana.lima@example.com", "(81) 98888-0002", "Estudante de Sistemas", "oficinas-0", null).pendente())));
