        testes.add(DynamicTest.dynamicTest("avaliacoes/nota: obrigatório", () -> assertThrows(ErroDominio.class, () -> new AvaliacaoExperiencia(Controle.novo(Estado.ATIVO), null, "Conteúdo da oficina", "Encontrei facilmente as informações de que precisava.", "", "oficinas-3"))));
        testes.add(DynamicTest.dynamicTest("avaliacoes/nota: abaixo do mínimo", () -> assertThrows(ErroDominio.class, () -> new AvaliacaoExperiencia(Controle.novo(Estado.ATIVO), 0, "Conteúdo da oficina", "Encontrei facilmente as informações de que precisava.", "", "oficinas-3"))));
        testes.add(DynamicTest.dynamicTest("avaliacoes/nota: acima do máximo", () -> assertThrows(ErroDominio.class, () -> new AvaliacaoExperiencia(Controle.novo(Estado.ATIVO), 6, "Conteúdo da oficina", "Encontrei facilmente as informações de que precisava.", "", "oficinas-3"))));
        testes.add(DynamicTest.dynamicTest("avaliacoes/aspecto: obrigatório", () -> assertThrows(ErroDominio.class, () -> new AvaliacaoExperiencia(Controle.novo(Estado.ATIVO), 4, null, "Encontrei facilmente as informações de que precisava.", "", "oficinas-3"))));
