        testes.add(DynamicTest.dynamicTest("avaliacoes/comentario: obrigatório", () -> assertThrows(ErroDominio.class, () -> new AvaliacaoExperiencia(Controle.novo(Estado.ATIVO), 4, "Conteúdo da oficina", null, "", "oficinas-3"))));
        testes.add(DynamicTest.dynamicTest("avaliacoes/comentario: texto extenso", () -> assertThrows(ErroDominio.class, () -> new AvaliacaoExperiencia(Controle.novo(Estado.ATIVO), 4, "Conteúdo da oficina", "", "", "oficinas-3"))));
        testes.add(DynamicTest.dynamicTest("avaliacoes/comentario: texto curto", () -> assertThrows(ErroDominio.class, () -> new AvaliacaoExperiencia(Controle.novo(Estado.ATIVO), 4, "Conteúdo da oficina", "x", "", "oficinas-3"))));
        testes.add(DynamicTest.dynamicTest("avaliacoes/nome: opcional", () -> assertDoesNotThrow(() -> new AvaliacaoExperiencia(Controle.novo(Estado.ATIVO), 4, "Conteúdo da oficina", "Encontrei facilmente as informações de que precisava.", null, "oficinas-3"))));
        testes.add(DynamicTest.dynamicTest("avaliacoes/nome: texto extenso", () -> assertThrows(ErroDominio.class, () -> new AvaliacaoExperiencia(Controle.novo(Estado.ATIVO), 4, "Conteúdo da oficina", "Encontrei facilmente as informações de que precisava.", "xxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxx", "oficinas-3"))));
        testes.add(DynamicTest.dynamicTest("avaliacoes/nome: texto curto", () -> assertThrows(ErroDominio.class, () -> new AvaliacaoExperiencia(Controle.novo(Estado.ATIVO), 4, "Conteúdo da oficina", "Encontrei facilmente as informações de que precisava.", "x", "oficinas-3"))));
        testes.add(DynamicTest.dynamicTest("avaliacoes/oficina: obrigatório", () -> assertThrows(ErroDominio.class, () -> new AvaliacaoExperiencia(Controle.novo(Estado.ATIVO), 4, "Conteúdo da oficina", "Encontrei facilmente as informações de que precisava.", "", null))));
        testes.add(DynamicTest.dynamicTest("avaliacoes/oficina: identidade inválida", () -> assertThrows(ErroDominio.class, () -> new AvaliacaoExperiencia(Controle.novo(Estado.ATIVO), 4, "Conteúdo da oficina", "Encontrei facilmente as informações de que precisava.", "", "duas palavras"))));
        testes.add(DynamicTest.dynamicTest("atendimentos: exemplo válido", () -> assertDoesNotThrow(() -> new SolicitacaoAtendimento(Controle.novo(Estado.ATIVO), "Como enviar uma sugestão?", "Gostaria de sugerir um tema para uma próxima oficina.", "Dúvida"))));
